/* SOC presentation and investigation context. All data is synthetic and memory-only. */
window.ADTR_SOC = function (api) {
  'use strict';
  const {state, escape:esc, icon, tag, btn, link, role, permission, visibleEvents, visibleAssets, visibleTasks, render, setRoute, toast} = api;
  const defaults = () => ({q:'',status:'all',severity:'all',owner:'all',window:'24h',sort:'risk'});
  let initialized=false;
  let filters=defaults(), selection={tab:'overview',node:null,edge:null,text:false}, origin=null;
  const levelOrder={'高危':3,'中危':2,'低危':1};
  const reference=Date.parse('2026-10-10T00:10:00Z');
  const caseData={
    e1:{reason:'敏感目录访问命中身份异常规则，关联身份具备特权组成员关系。', gap:'尚未关联到已批准的变更工单，需要核实访问目的。', evidence:[
      {id:'ev-e1-access',title:'访问敏感目录对象',event:'4662',source:'Windows 安全日志',time:'23:58:42',from:'a1',to:'a3',relation:'目录对象访问',detail:'demo.alex 访问 DEMO-Tier0 对象；命中规则 DEMO-IDENTITY-021。',confidence:'已观测'},
      {id:'ev-e1-member',title:'特权组成员快照',event:'目录快照',source:'DEMO-BATCH-001',time:'23:55:00',from:'a1',to:'a3',relation:'成员关系',detail:'当前目录快照中，demo.alex 属于 DEMO-Tier0。',confidence:'已观测'}]},
    e2:{reason:'服务身份首次从该工作站发起认证，与已观测设备关系不同。',gap:'缺少更早的认证基线，首次出现不代表未经授权。请核实维护窗口。',evidence:[
      {id:'ev-e2-auth',title:'工作站认证成功',event:'4624',source:'Windows 安全日志',time:'23:46:18',from:'a5',to:'a4',relation:'认证登录',detail:'DEMO-WS-012 使用 demo.service 完成认证。',confidence:'已观测'},
      {id:'ev-e2-baseline',title:'设备关系首次出现',event:'关系对比',source:'DEMO-AUTH-014 / v1.4.2',time:'23:46:18',from:'a5',to:'a4',relation:'新访问关系',detail:'当前观测窗口内首次记录该设备与服务身份的认证关系。',confidence:'窗口内首次'}]},
    e3:{reason:'敏感组的前后成员快照不同，变化触发目录保护规则。',gap:'当前证据未包含变更发起身份，不能据此归因到某位用户。',evidence:[
      {id:'ev-e3-change',title:'敏感组成员变化',event:'4728',source:'Windows 安全日志',time:'23:32:06',from:null,to:'a3',relation:'成员变化',detail:'DEMO-Tier0 成员关系发生变化；变更发起身份未采集。',confidence:'已观测'}]}
  };
  function asset(id){return visibleAssets().find(a=>a.id===id);}
  function owner(e){return e.assignee??(e.id==='e2'?'安全负责人':'未分派');}
  function dossier(e){return caseData[e.id]||{reason:e.evidence,gap:'请结合变更授权与来源设备的观测，核实业务上下文。',evidence:[{id:'ev-'+e.id,title:e.title,event:e.rule,source:'安全事件记录',time:e.time,from:null,to:e.asset,relation:'关联对象',detail:e.evidence,confidence:'已观测'}]};}
  function scopedEvents(){return visibleEvents().filter(e=>filters.window!=='1h'||reference-Date.parse('2026-10-09T'+e.time+'Z')<=3600000);}
  function currentEvent(){return visibleEvents().find(e=>e.id===state.investigationId);}
  function eventTasks(e){return visibleTasks().filter(t=>t.kind==='response'&&t.target?.eventId===e.id);}
  function filtered(){return scopedEvents().filter(e=>{
    const a=asset(e.asset), text=[e.title,e.id,e.rule,a?.name,api.domains[e.domain]].join(' ').toLowerCase();
    return (!filters.q||text.includes(filters.q.toLowerCase()))&&(filters.status==='all'||(filters.status==='open'?e.state!=='已关闭':e.state===filters.status))&&(filters.severity==='all'||e.level===filters.severity)&&(filters.owner==='all'||(filters.owner==='mine'?owner(e)===role().name:owner(e)==='未分派'));
  }).sort((a,b)=>filters.sort==='time'?b.time.localeCompare(a.time):filters.sort==='oldest'?a.time.localeCompare(b.time):(levelOrder[b.level]-levelOrder[a.level]||b.time.localeCompare(a.time)));}
  function presetButton(label,value,key,count,tone=''){return `<button class="soc-stat ${tone}" data-action="soc-preset" data-key="${key}" data-value="${value}"><span>${label}</span><strong>${count}<small> ${icon('arrow')}</small></strong></button>`;}
  function statusTone(s){return s==='待调查'?'amber':s==='调查中'?'blue':'outline';}
  function queueToolbar(){
    const chips=Object.entries(filters).filter(([k,v])=>!['sort','window','status'].includes(k)&&v&&v!=='all').map(([k,v])=>`<button class="soc-chip" data-action="soc-clear-filter" data-key="${k}">${esc(({q:'搜索',status:'状态',severity:'风险',owner:'负责人'})[k])}：${esc(v==='mine'?'分派给我':v==='unassigned'?'未分派':v==='open'?'未处理':v)} ${icon('close')}</button>`).join('');
    return `<div class="soc-queue-toolbar"><label class="search">${icon('search')}<input id="soc-query" type="search" data-soc-filter="q" value="${esc(filters.q)}" placeholder="搜索告警、身份或规则" aria-label="搜索告警队列"></label><select class="filter" id="soc-filter-severity" data-soc-filter="severity" aria-label="告警严重度"><option value="all">全部风险</option>${['高危','中危','低危'].map(v=>`<option ${filters.severity===v?'selected':''}>${v}</option>`).join('')}</select><select class="filter" id="soc-filter-owner" data-soc-filter="owner" aria-label="告警负责人"><option value="all">全部负责人</option><option value="mine" ${filters.owner==='mine'?'selected':''}>分派给我</option><option value="unassigned" ${filters.owner==='unassigned'?'selected':''}>未分派</option></select><select class="filter" id="soc-filter-sort" data-soc-filter="sort" aria-label="告警排序"><option value="risk" ${filters.sort==='risk'?'selected':''}>风险优先</option><option value="time" ${filters.sort==='time'?'selected':''}>最近发生</option><option value="oldest" ${filters.sort==='oldest'?'selected':''}>最早发生</option></select></div>${chips?`<div class="soc-filter-chips">${chips}<button class="soc-text-button" data-action="soc-reset">清除全部</button></div>`:''}`;
  }
  function queueTable(events,compact=false){return `<div class="table-scroll soc-table-scroll" role="region" aria-label="告警队列表" tabindex="0"><table class="soc-table"><thead><tr><th>风险</th><th>告警 / 最近发生</th><th>关联身份</th><th>负责人</th><th>状态</th><th>证据</th></tr></thead><tbody>${events.map(e=>{const a=asset(e.asset);return `<tr data-soc-event="${e.id}"><td><span class="soc-severity severity-${e.level==='高危'?'high':e.level==='中危'?'medium':'low'}">${e.level}</span></td><td><button class="row-link" data-action="event-detail" data-id="${e.id}">${esc(e.title)}</button><span class="row-sub">${e.id.toUpperCase()} <span class="soc-sep">·</span> 10-09 ${e.time}</span></td><td><span class="soc-identity">${esc(a?.name||'无资产读取权限')}</span><span class="row-sub">${esc(e.domain)}</span></td><td><span class="${owner(e)==='未分派'?'muted':''}">${esc(owner(e))}</span></td><td>${tag(e.state,statusTone(e.state))}</td><td class="mono muted">${dossier(e).evidence.length}</td></tr>`;}).join('')}</tbody></table></div>`;}
  function queuePanel(compact=false){
    const list=filtered(), tabs=[['open','未处理'],['all','全部'],['待调查','待调查'],['调查中','调查中'],['已关闭','已关闭']];
    return `<section class="panel soc-queue" data-testid="overview-pending"><div class="soc-panel-heading"><h2>${compact?'优先处理':'告警队列'}</h2><span class="soc-count">${list.length} 条</span>${compact?link('完整队列 '+icon('arrow'),'threats','soc-heading-link'):btn(icon('download')+'导出证据','export-events','subtle',api.exportAllowed('events')?'':'disabled')}</div><div class="soc-view-tabs">${tabs.map(([v,t])=>`<button data-action="soc-status" data-value="${v}" class="${filters.status===v?'active':''}">${t}<span>${v==='all'?scopedEvents().length:v==='open'?scopedEvents().filter(e=>e.state!=='已关闭').length:scopedEvents().filter(e=>e.state===v).length}</span></button>`).join('')}</div>${queueToolbar()}${list.length?queueTable(list,compact):'<div class="soc-empty-inline">没有符合条件的告警。调整筛选后重试。</div>'}<div class="soc-table-foot"><span>当前结果 ${list.length} 条 / 授权告警 ${scopedEvents().length} 条</span><span>观测时间 UTC · 2026-10-09</span></div></section>`;
  }
  function taskSummary(){const pending=visibleTasks().filter(t=>t.kind==='response'&&['unknown','failed','cancel_requested'].includes(t.state));return `<section class="panel soc-attention" data-testid="overview-processing"><div class="soc-panel-heading"><h2>需要核对的响应</h2>${icon('response')}</div>${pending.length?pending.slice(0,3).map(t=>`<button class="soc-attention-row" data-action="task-detail" data-id="${t.id}"><span>${esc(t.target?.name||t.title)}<small>${esc(api.taskLabel(t))}</small></span>${icon('chevron')}</button>`).join(''):`<div class="soc-clear-state"><span class="soc-ok-icon">${icon('check')}</span><strong>当前没有待核对响应</strong><p>提交后的执行结果会保留在此处。</p></div>`}<div class="soc-throughput-line"><span>最近 24 小时已关闭 ${visibleEvents().filter(e=>e.state==='已关闭').length} 起</span><span>${(visibleEvents().filter(e=>e.state==='已关闭').length/24).toFixed(2)} 起 / 小时</span></div><div class="soc-attention-footer">${link('响应记录','response/history','soc-text-link')}<span>${visibleTasks().filter(t=>t.kind==='response'&&t.state==='succeeded').length} 项已完成</span></div></section>`;}
  function latestDetection(){const rows=api.recentDetection();return `<section class="panel" data-testid="overview-latest-detection"><div class="soc-panel-heading"><h2>最近检测</h2>${link('全部','detection','soc-heading-link')}</div><div class="soc-list">${rows.slice(0,3).map(r=>`<a class="soc-detection-row" href="#/detection/baseline"><span>${icon('detect')}</span><span><strong>${esc(r.name)}</strong><small>${esc(r.domain)} · 10-10 00:00</small></span>${tag(r.status,r.status==='通过'?'green':r.status==='未通过'?'amber':'outline')}</a>`).join('')||'<p class="soc-empty-inline">暂无可见检测结果</p>'}</div></section>`;}
  function lowerPanels(){
    const ev=visibleEvents(),assets=visibleAssets(),histories={alpha:[8,12,10,18,13,15,9],beta:[4,6,5,8,5,8,5]},keys=permission('investigationView')?Object.keys(histories).filter(api.domainAllowed):[];
    const series=Array.from({length:7},(_,i)=>keys.reduce((n,k)=>n+histories[k][i],0)),max=Math.max(1,...series),total=series.reduce((n,x)=>n+x,0),targets=assets.filter(a=>ev.some(e=>e.asset===a.id)).sort((a,b)=>b.risk-a.risk).slice(0,4);
    return `<div class="soc-lower-grid"><section class="panel" data-testid="overview-trend"><div class="soc-panel-heading"><h2>告警趋势</h2><span class="muted">最近 7 日 · ${total} 起</span></div><div class="soc-mini-chart" role="img" aria-label="当前授权域最近7日告警共${total}起"><svg viewBox="0 0 600 145" preserveAspectRatio="none" aria-hidden="true"><path class="soc-chart-grid" d="M10 25H590 M10 70H590 M10 115H590"/><path class="soc-chart-fill" d="M10 120 ${series.map((n,i)=>'L'+(10+i*96)+','+(118-n/max*94)).join(' ')} L586 120Z"/><polyline class="soc-chart-line" points="${series.map((n,i)=>(10+i*96)+','+(118-n/max*94)).join(' ')}"/></svg><div class="soc-chart-dates">${['03','04','05','06','07','08','09'].map(d=>`<span>10/${d}</span>`).join('')}</div></div></section><section class="panel" data-testid="overview-targets"><div class="soc-panel-heading"><h2>重点关注身份</h2>${link('资产目录','assets','soc-heading-link')}</div><div class="soc-risk-list" data-testid="overview-heat">${targets.map(a=>`<button data-action="asset-detail" data-id="${a.id}"><span class="soc-entity-mark">${icon(a.type==='计算机'?'server':a.type==='组'?'group':'user')}</span><span><strong>${esc(a.name)}</strong><small>${esc(a.domain)} · ${ev.filter(e=>e.asset===a.id).length} 条告警 · ${ev.filter(e=>e.asset===a.id&&e.level==='高危').length} 高危</small></span><span class="soc-risk-score">${a.risk}<small>风险</small></span></button>`).join('')||'<p class="soc-empty-inline">暂无可见身份风险</p>'}</div><div class="soc-attention-footer"><span>已完成响应 ${visibleTasks().filter(t=>t.kind==='response'&&t.state==='succeeded').length} 项</span><span>待核对 ${visibleTasks().filter(t=>t.kind==='response'&&t.state==='unknown').length} 项</span></div></section></div>`;
  }
  function dashboard(){if(!initialized){filters.status='open';initialized=true;}const ev=scopedEvents(),open=ev.filter(e=>e.state!=='已关闭');return `<div class="soc-page-title"><div><span class="soc-kicker">SECURITY OPERATIONS</span><h1 id="page-title" tabindex="-1">安全工作台</h1></div><div class="soc-time-scope">${icon('clock')}<select aria-label="工作台时间范围" id="soc-filter-window" data-soc-filter="window"><option value="24h" ${filters.window==='24h'?'selected':''}>最近 24 小时</option><option value="1h" ${filters.window==='1h'?'selected':''}>最近 1 小时</option></select><span>UTC</span></div></div><section class="soc-stat-strip" data-testid="overview-workload">${presetButton('未处理告警','open','status',open.length)}${presetButton('高危待调查','high-open','preset',ev.filter(e=>e.level==='高危'&&e.state==='待调查').length,'urgent')}${presetButton('分派给我','mine','owner',ev.filter(e=>e.state!=='已关闭'&&owner(e)===role().name).length)}${presetButton('尚未分派','unassigned','owner',ev.filter(e=>e.state!=='已关闭'&&owner(e)==='未分派').length)}</section><div class="soc-work-grid"><div>${queuePanel(true)}${lowerPanels()}</div><aside class="soc-sidebar-panels">${taskSummary()}${latestDetection()}<div class="soc-data-quality" data-testid="overview-health">${icon('activity')}<div><strong>资产与接入观测</strong><span>${permission('assetView')?visibleAssets().length+' 项资产 · '+new Set(visibleAssets().map(a=>a.domain)).size+' 个可见域':'无资产读取权限'}</span><span>${permission('assetView')?visibleAssets().filter(a=>!a.seen).length+' 项缺少最后观测时间':''}</span><span>${permission('systemView')?state.domains.filter(d=>api.domainAllowed(d.id)&&d.diagnostic==='success').length+' 个域历史诊断通过 · '+state.domains.filter(d=>api.domainAllowed(d.id)&&d.diagnostic!=='success').length+' 个域观测陈旧':'接入观测无读取权限'}</span></div>${link('核查','assets','soc-text-link')}</div></aside></div>`;}
  function queuePage(){if(!initialized){filters.status='all';initialized=true;}return `<div class="soc-page-title"><div><span class="soc-kicker">DETECTION & TRIAGE</span><h1 id="page-title" tabindex="-1">告警队列</h1><p>筛选、研判并分派告警，保留每一步调查上下文。</p></div><div class="soc-time-scope">${icon('clock')}<select aria-label="队列时间范围" id="soc-filter-window" data-soc-filter="window"><option value="24h" ${filters.window==='24h'?'selected':''}>最近 24 小时</option><option value="1h" ${filters.window==='1h'?'selected':''}>最近 1 小时</option></select></div></div>${queuePanel()}<div class="related-links"><span>调查工具</span>${link('行为检索','threats/search')}${link('攻击路径','threats/paths')}${link('蜜罐监控','threats/honeypots')}</div>`;}
  function evidenceTable(e,records){return `<div class="table-scroll soc-table-scroll" tabindex="0" role="region" aria-label="调查证据表"><table class="soc-table soc-evidence-table"><thead><tr><th>观测时间 UTC</th><th>证据</th><th>来源 / 记录</th><th>关系判断</th></tr></thead><tbody>${records.map(r=>`<tr class="${selection.edge===r.id?'selected':''}"><td class="mono" data-label="观测时间 UTC">${r.time}</td><td data-label="证据"><button class="row-link" data-action="soc-evidence" data-id="${r.id}">${esc(r.title)}</button><span class="row-sub">${esc(r.detail)}</span></td><td data-label="来源 / 记录">${esc(r.source)}<span class="row-sub mono">${esc(r.event)}</span></td><td data-label="关系判断">${tag(r.confidence,'outline')}</td></tr>`).join('')}</tbody></table></div>`;}
  function graph(e){
    const d=dossier(e),ids=[...new Set([...d.evidence.flatMap(r=>[r.from,r.to]).filter(Boolean),e.asset])];
    const nodes=ids.map(asset).filter(a=>a&&a.domain===e.domain);
    const edges=d.evidence.filter(r=>r.from&&r.to&&nodes.some(n=>n.id===r.from)&&nodes.some(n=>n.id===r.to));
    const active=nodes.find(n=>n.id===selection.node)||nodes.find(n=>n.id===e.asset),activeEdge=d.evidence.find(r=>r.id===selection.edge);
    const diagramWidth=window.matchMedia?.('(max-width:760px)')?.matches?360:760,center=diagramWidth/2,fromX=diagramWidth/4+32,toX=diagramWidth*3/4-32;
    const nodeMarkup=nodes.map((n,i)=>`<button class="soc-graph-node node-${nodes.length===1?'single':i} ${n.id===active?.id?'active':''} ${activeEdge&&(activeEdge.from===n.id||activeEdge.to===n.id)?'related':''}" data-action="soc-node" data-id="${n.id}"><span>${icon(n.type==='计算机'?'server':n.type==='组'?'group':'user')}</span><strong>${esc(n.name)}</strong><small>${esc(n.type)} · ${esc(n.domain)}</small></button>`).join('');
    const lines=edges.map((r,i)=>{const below=i%2===1;return `<g class="soc-directed-edge ${selection.edge===r.id?'active':''} ${r.confidence==='已观测'?'observed':'windowed'}"><path data-edge-id="${r.id}" d="M${fromX} ${below?94:80} C${center-60} ${below?190:12} ${center+60} ${below?190:12} ${toX} ${below?94:80}" marker-end="url(#soc-edge-arrow)"><title>${esc(r.relation)} · ${r.time}</title></path></g>`;}).join('');
    const edgeCaptions=edges.map((r,i)=>`<button class="soc-edge-caption edge-${i%2} ${selection.edge===r.id?'active':''}" data-action="soc-edge" data-id="${r.id}"><strong>${esc(r.relation)}</strong><span>${r.time} · 1 条证据</span></button>`).join('');
    return `<section class="panel soc-investigation-graph"><div class="soc-panel-heading"><h2>实体与关系</h2><span class="soc-count">${nodes.length} 个实体 / ${edges.length} 条关系</span><button class="soc-text-button" data-action="soc-graph-view">${selection.text?'关系图':'文字视图'}</button></div><div class="soc-graph-layout"><div class="soc-graph-main ${selection.text?'text-mode':''}">${nodes.length?`<div class="soc-graph-diagram"><svg class="soc-edge-canvas" viewBox="0 0 ${diagramWidth} 220" preserveAspectRatio="none" aria-label="实体间已观测关系"><defs><marker id="soc-edge-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10 Z"/></marker></defs>${lines}</svg>${edgeCaptions}<div class="soc-graph-nodes">${nodeMarkup}</div></div><div class="soc-edge-list">${edges.map(r=>`<button class="${selection.edge===r.id?'active':''}" data-action="soc-edge" data-id="${r.id}"><span>${esc(asset(r.from)?.name)}</span>${icon('arrow')}<strong>${esc(r.relation)}</strong>${icon('arrow')}<span>${esc(asset(r.to)?.name)}</span><small>${r.time} · ${esc(r.confidence)}</small></button>`).join('')||'<div class="soc-evidence-gap">未采集到可核验的实体间关系，当前仅展示关联对象。</div>'}</div>`:'<div class="soc-evidence-gap">当前角色没有关联资产的读取权限。</div>'}<div class="soc-graph-legend"><span>实线：已观测关系</span><span>虚线：窗口内判断，需核实</span></div></div><aside class="soc-entity-detail">${active?`<div class="soc-entity-header"><span class="soc-entity-mark">${icon(active.type==='计算机'?'server':active.type==='组'?'group':'user')}</span><div><strong>${esc(active.name)}</strong><span>${esc(api.domains[active.domain])}</span></div></div><dl><div><dt>对象类型</dt><dd>${esc(active.type)}</dd></div><div><dt>身份风险</dt><dd>${active.risk} / 100</dd></div><div><dt>对象 GUID</dt><dd class="mono">${esc(active.guid)}</dd></div><div><dt>最后观测</dt><dd>${esc(api.assetObservedAt(active)||'未观测')}</dd></div></dl>${btn('查看资产详情 '+icon('arrow'),'soc-asset','',`data-id="${active.id}"`)}${activeEdge?`<div class="soc-selected-evidence"><strong>${esc(activeEdge.relation)}</strong><p>${esc(activeEdge.detail)}</p><small>${esc(activeEdge.source)} · ${activeEdge.time}</small></div>`:''}`:'<p class="soc-empty-inline">请选择有权访问的实体。</p>'}</aside></div></section>`;
  }
  function responseResults(e){const tasks=eventTasks(e);return `<div class="soc-panel-heading"><h2>响应与执行记录</h2><span class="soc-count">${tasks.length}</span></div>${tasks.length?tasks.map(t=>`<div class="soc-response-task"><div><strong>${esc(t.target.name)}</strong><span>${esc(t.target.effect)} · ${esc(t.id)}</span></div>${tag(api.taskLabel(t),t.state==='succeeded'?'green':['unknown','failed'].includes(t.state)?'amber':'blue')}${btn('详情','task-detail','subtle',`data-id="${t.id}"`)}${t.state==='unknown'&&t.epoch===state.epoch&&api.canOperation('task')?btn('核对原请求','reconcile-task','',`data-id="${t.id}"`):''}</div>`).join(''):'<div class="soc-empty-inline">本事件尚未提交响应。核实证据与影响后，再发起操作。</div>'}`;}
  function investigation(){const e=currentEvent();if(!e)return api.empty('调查不可用或无访问权限','请返回当前授权范围内的告警队列。',link('返回告警队列','threats','button primary'),'lock');if(selection.caseId!==e.id)selection={caseId:e.id,tab:'overview',node:e.asset,edge:null,text:false};const d=dossier(e),a=asset(e.asset),evidence=selection.edge?d.evidence.filter(r=>r.id===selection.edge):d.evidence;
    return `<div class="soc-case-breadcrumb"><button data-action="soc-return">${icon('chevron')}返回告警队列</button><span>/</span><span>${e.id.toUpperCase()}</span></div><header class="soc-case-header"><div><div class="soc-case-eyebrow"><span class="soc-severity severity-${e.level==='高危'?'high':e.level==='中危'?'medium':'low'}">${e.level}</span><span>${esc(api.domains[e.domain])}</span><span>${e.id.toUpperCase()}</span></div><h1 id="page-title" tabindex="-1">${esc(e.title)}</h1><div class="soc-case-meta"><span>首次观测 <b>10-09 ${e.time} UTC</b></span><span>负责人 <b>${esc(owner(e))}</b></span>${tag(e.state,statusTone(e.state))}</div></div><div class="soc-case-actions">${btn('分派给我','soc-assign','',api.canOperation('investigation')?'':'disabled')}${btn('关闭事件','event-close','',`data-id="${e.id}" ${api.canOperation('investigation')?'':'disabled'}`)}${btn(icon('response')+(eventTasks(e).some(t=>['queued','running','cancel_requested','unknown'].includes(t.state))?'查看原响应':'响应 '+esc(a?.name||'事件对象')),'soc-response','primary',api.canOperation('response')?'':'disabled')}</div></header><nav class="soc-case-tabs" aria-label="调查视图">${[['overview','调查概览'],['evidence','证据 '+d.evidence.length],['activity','活动与响应'+(eventTasks(e).length?' '+eventTasks(e).length:'')]].map(([key,name])=>`<button class="${selection.tab===key?'active':''}" data-action="soc-case-tab" data-tab="${key}">${name}</button>`).join('')}</nav>${selection.tab==='overview'?`<div class="soc-finding-summary ${selection.summaryExpanded?'expanded':''}"><section><span>触发原因</span><p>${esc(d.reason)}</p></section><section class="soc-known-facts"><span>已知事实</span><p>${esc(e.evidence)}</p></section><section class="needs-check"><span>待核实</span><p>${esc(d.gap)}</p></section><button class="soc-mobile-summary" data-action="soc-summary">${selection.summaryExpanded?'收起已知事实':'展开已知事实'}</button></div><div class="soc-investigation-stack">${graph(e)}<section class="panel soc-evidence-panel"><div class="soc-panel-heading"><h2>关联证据</h2><span class="soc-count">${evidence.length} 条</span>${selection.edge?btn('显示全部','soc-clear-edge','subtle'):''}</div>${evidenceTable(e,evidence)}</section></div>`:selection.tab==='evidence'?`<section class="panel"><div class="soc-panel-heading"><h2>证据记录</h2><span class="muted">规则 ${esc(e.rule)} / v1.4.2</span></div>${evidenceTable(e,d.evidence)}<div class="soc-raw-evidence"><h3>来源字段</h3><pre>Event: ${esc(e.id)}\nRule: ${esc(e.rule)}\nDomain: ${esc(api.domains[e.domain])}\nAsset: ${esc(a?.guid||'无资产读取权限')}\nObserved: 2026-10-09T${e.time}Z</pre></div></section>`:`<div class="soc-activity-grid"><section class="panel"><div class="soc-panel-heading"><h2>调查活动</h2></div><ol class="soc-case-timeline"><li><span class="soc-timeline-dot"></span><small>10-09 ${e.time} UTC</small><strong>告警生成</strong><p>${esc(d.reason)}</p></li>${(e.activity||[]).map(x=>`<li><span class="soc-timeline-dot"></span><small>${esc(x.time)} · ${esc(x.actor)}</small><strong>${esc(x.title)}</strong><p>${esc(x.text)}</p></li>`).join('')}${eventTasks(e).flatMap(t=>t.events.map(x=>`<li><span class="soc-timeline-dot response"></span><small>${esc(x.time)} · ${esc(t.id)}</small><strong>${esc(api.taskLabel(t))}</strong><p>${esc(x.text)}</p></li>`)).join('')}</ol></section><section class="panel soc-response-results">${responseResults(e)}</section></div>`}<div class="soc-investigation-footer"><span>${icon('lock')}仅显示当前授权域内的证据与对象</span><span>观测与响应结果分别保留</span></div>`;
  }
  function open(eid){const e=visibleEvents().find(e=>e.id===eid);if(!e)return;origin={path:state.route==='overview'?'overview':'threats',scroll:window.scrollY||0,event:e.id};selection={tab:'overview',node:e.asset,edge:null,text:false};setRoute('threats/investigation/'+e.id);}
  function addActivity(e,title,text){(e.activity||(e.activity=[])).push({time:'10-10 00:10 UTC',actor:role().name,title,text});}
  function updateFilter(el){filters[el.dataset.socFilter]=el.value;const pos=el.selectionStart;render();if(el.id){const next=document.getElementById(el.id);next?.focus({preventScroll:true});if(pos!==null&&next?.type==='search')next.setSelectionRange(pos,pos);}return true;}
  function clearContext(){initialized=false;filters=defaults();selection={tab:'overview',node:null,edge:null,text:false};origin=null;state.investigationId=null;}
  const actions={
    'soc-open':el=>open(el.dataset.id),
    'soc-status':el=>{filters.status=el.dataset.value;render();},
    'soc-clear-filter':el=>{filters[el.dataset.key]=el.dataset.key==='q'?'':'all';render();},
    'soc-reset':()=>{filters=defaults();if(state.route==='overview')filters.status='open';render();},
    'soc-preset':el=>{const window=filters.window;filters=defaults();filters.window=window;if(el.dataset.key==='preset'){filters.status='待调查';filters.severity='高危';}else {filters[el.dataset.key]=el.dataset.value;if(el.dataset.key==='owner')filters.status='open';}initialized=true;setRoute('threats');},
    'soc-case-tab':el=>{selection.tab=el.dataset.tab;render();},
    'soc-node':el=>{selection.node=el.dataset.id;selection.edge=null;render();},
    'soc-edge':el=>{const e=currentEvent(),r=e&&dossier(e).evidence.find(r=>r.id===el.dataset.id);if(!r)return;selection.edge=r.id;selection.node=r.to;render();},
    'soc-evidence':el=>{const e=currentEvent(),r=e&&dossier(e).evidence.find(r=>r.id===el.dataset.id);if(!r)return;selection.tab='overview';selection.edge=r.id;selection.node=r.to;render();},
    'soc-clear-edge':()=>{selection.edge=null;render();},
    'soc-summary':()=>{selection.summaryExpanded=!selection.summaryExpanded;render();},
    'soc-graph-view':()=>{selection.text=!selection.text;render();},
    'soc-asset':el=>api.previewAsset(el.dataset.id),
    'soc-assign':()=>{const e=currentEvent();if(!e||!api.canOperation('investigation'))return;e.assignee=role().name;e.state='调查中';addActivity(e,'分派调查','事件已分派给 '+role().name);api.audit('分派调查',e.id,'成功',e.domain);render();toast('已分派给你，并标为调查中。');},
    'soc-response':()=>{const e=currentEvent();if(e)api.beginResponse(e);},
    'soc-return':()=>{const saved=origin;setRoute(saved?.path||'threats');queueMicrotask(()=>{window.scrollTo?.(0,saved?.scroll||0);if(saved?.event)document.querySelector(`[data-action="event-detail"][data-id="${saved.event}"]`)?.focus({preventScroll:true});});}
  };
  return {dashboard,queuePage,investigation,open,clearContext,addActivity,actions,onClick:e=>{const edge=e.target.closest?.('[data-edge-id]');if(!edge)return false;actions['soc-edge']({dataset:{id:edge.dataset.edgeId}});return true;},onKeyDown:e=>{if(['Enter',' '].includes(e.key)&&e.target?.getAttribute?.('role')==='button'&&e.target.dataset?.action==='soc-edge'){e.preventDefault();actions['soc-edge'](e.target);return true;}return false;},onInput:el=>el.dataset.socFilter==='q'?updateFilter(el):false,onChange:el=>el.dataset.socFilter&&el.dataset.socFilter!=='q'?updateFilter(el):false};
};
